node <<'NODE'
const {runCli}=require('./.github/scripts/codex-fallback.cjs');
const {codexStatusFor}=require('./.github/scripts/acceptance-readiness.cjs');
const head='a'.repeat(40), base='b'.repeat(40);
const out='.planning/phases/85-example/codex/aaaaaaaaaaaa-task-a2';
const fallback={schema:1,pr:90,head,base,codex_out:out,reviewer:{name:'vibe-check deep review',kind:'vibe-check-deep-review'},scope:{head,base,diff:'full'},result:{status:'complete',summary:'Independent review of the full range completed.',findings:[]},owner_decision:{decision:'approve-fallback',verbatim:'I approve the fallback for '+head,decided_at:'2026-10-28T12:00:00Z'}};
const meta={head,base,attempt:2,review_mode:'trusted-local-tests',audited_inputs_changed_in_diff:['tests/codex_report_status.py']};
const status={status:'complete',inspected_head:head,inspected_base:base};
const baseStatus={status:'incomplete',reasons:['base checker could not run: OSError']};
const files={'fallback.json':fallback,[out+'.meta.json']:meta,[out+'.status.json']:status,[out+'.base-status.json']:baseStatus};
const exit=runCli(['validate','--file','fallback.json','--pr','90','--head',head,'--base',base,'--pr-author','thejuran','--head-trust','trusted','--codex-out',out],{readFileSync:p=>JSON.stringify(files[p]),log:console.log,error:console.error});
console.log('fallback validator exit:',exit);
console.log('readiness:',codexStatusFor({head,base,pr:90,prAuthor:'thejuran',headTrust:'trusted',meta,status,baseStatus,out,fallback}));
NODE
